do $val$
declare
  v_topics int; v_lessons int; v_practice int; v_tests int; v_questions int; v_web boolean; v_mob boolean;
begin
  select count(*) into v_topics from public.learning_topics where source_kind = 'spring_boot_tutorial' and source_ref in ($sb259$production/caching-in-spring-boot$sb259$, $sb260$production/scheduling-with-scheduled$sb260$, $sb261$production/async-processing-with-async$sb261$, $sb262$production/spring-events$sb262$, $sb263$production/sending-email$sb263$, $sb264$production/swagger-and-openapi-documentation$sb264$, $sb265$production/spring-aop$sb265$, $sb266$production/interceptors-and-filters$sb266$);
  if v_topics <> 8 then raise exception 'validation: expected 8 topics, found %', v_topics; end if;
  select count(*) filter (where c.metadata ->> 'block' = 'lesson'), count(*) filter (where c.metadata ->> 'block' = 'practice')
    into v_lessons, v_practice
    from public.learning_contents c join public.learning_topics t on t.id = c.topic_id
   where c.metadata ->> 'source' = 'spring_boot_seed' and t.source_kind = 'spring_boot_tutorial' and t.source_ref in ($sb259$production/caching-in-spring-boot$sb259$, $sb260$production/scheduling-with-scheduled$sb260$, $sb261$production/async-processing-with-async$sb261$, $sb262$production/spring-events$sb262$, $sb263$production/sending-email$sb263$, $sb264$production/swagger-and-openapi-documentation$sb264$, $sb265$production/spring-aop$sb265$, $sb266$production/interceptors-and-filters$sb266$);
  if v_lessons <> 8 then raise exception 'validation: expected 8 lesson blocks, found %', v_lessons; end if;
  if v_practice <> 8 then raise exception 'validation: expected 8 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-caching-in-spring-boot', 'pt-sb-scheduling-with-scheduled', 'pt-sb-async-processing-with-async', 'pt-sb-spring-events', 'pt-sb-sending-email', 'pt-sb-swagger-and-openapi-documentation', 'pt-sb-spring-aop', 'pt-sb-interceptors-and-filters') and learning_topic_id is not null;
  if v_tests <> 8 then raise exception 'validation: expected 8 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-sb-caching-in-spring-boot', 'pt-sb-scheduling-with-scheduled', 'pt-sb-async-processing-with-async', 'pt-sb-spring-events', 'pt-sb-sending-email', 'pt-sb-swagger-and-openapi-documentation', 'pt-sb-spring-aop', 'pt-sb-interceptors-and-filters');
  if v_questions <> 40 then raise exception 'validation: expected 40 MCQs, found %', v_questions; end if;
  select show_on_website, show_on_mobile into v_web, v_mob from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  raise notice '0136/108 OK: Spring Boot Tutorial batch 13: % topics, % lesson blocks, % practice blocks, % tests, % MCQs. Grid visible on website=%, mobile=%.',
    v_topics, v_lessons, v_practice, v_tests, v_questions, v_web, v_mob;
end
$val$;

notify pgrst, 'reload schema';
